import django
from django.conf import settings
settings.configure(
    INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
    DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
)
django.setup()
from django.db import models


class Mixin:
    def get_m_display(self):
        return 'from mixin'


class WithMixin(Mixin, models.Model):
    m = models.CharField(max_length=10, choices=[(1, 'a')])

    class Meta:
        app_label = 'edge_app'


class AbstractBase(models.Model):
    class Meta:
        abstract = True
        app_label = 'edge_app'

    def get_c_display(self):
        return 'from abstract'


class Child(AbstractBase):
    c = models.CharField(max_length=10, choices=[(1, 'a')])

    class Meta:
        app_label = 'edge_app'


class Sub(Child):
    class Meta:
        app_label = 'edge_app'


print('mixin ->', WithMixin(m=1).get_m_display())
print('abstract ->', Child(c=1).get_c_display())
print('subclass of override ->', Sub(c=1).get_c_display())
print('generated still ok ->', Child(c=1).get_c_display.__self__.get_c_display() if False else 'ok')
# choices-less field must not gain an accessor
class NoChoices(models.Model):
    n = models.CharField(max_length=10)
    class Meta:
        app_label = 'edge_app'
assert not hasattr(NoChoices, 'get_n_display')
print('no-choices ok')
EOF
